/* Simulated onboarding. Identity inputs live in memory only; no network requests. */
'use strict';
const CREDIT_ADVANCE_PERCENT=55;
function creditLimitForPledge(value){return Number.isSafeInteger(value)&&value>0?Math.ceil(value*55/100000)*1000:0}
function minimumPledgeForCredit(credit){if(!Number.isFinite(credit)||credit<=0)return 0;return Math.floor((Math.ceil(credit/1000)-1)*100000/55)+1}
const onboardingFunds=[
  {id:'hdfc',name:'HDFC Flexi Cap Fund',type:'Equity · Direct growth',value:500000,folio:'•• 1042',color:'hdfc'},
  {id:'parag',name:'Parag Parikh Flexi Cap',type:'Equity · Direct growth',value:400000,folio:'•• 8036',color:'parag'},
  {id:'icici',name:'ICICI Prudential Bluechip',type:'Equity · Direct growth',value:300000,folio:'•• 2901',color:'icici'}
];
const onboardingStepTitles=['Your details','Verify your phone','Find your portfolio','Choose your backing','Your credit limit','Review your limit','Verify your identity','Authorise your pledge','Mark your lien','Review & e-sign'];
function newOnboarding(){return{step:1,phone:'',pan:'',lookupConsent:false,phoneVerified:false,portfolioFetched:false,selected:{},amounts:{},limitSeen:false,limitReviewed:false,kycConsent:false,ckycVerified:false,lienOtpVerified:false,lienMarked:false,esignConsent:false,signature:'',busy:false,progress:0,error:''}}
let onboarding=newOnboarding(),onboardingTimers=[],onboardingProgressToken=0;
function onboardingSelection(){const funds=onboardingFunds.map(f=>({...f,pledged:onboarding.selected[f.id]?Number(onboarding.amounts[f.id]):0}));const valid=funds.every(f=>Number.isSafeInteger(f.pledged)&&f.pledged>=0&&f.pledged<=f.value)&&funds.some(f=>f.pledged>0)&&funds.every(f=>!onboarding.selected[f.id]||f.pledged>0);const pledged=funds.reduce((sum,f)=>sum+f.pledged,0);return{funds,valid,pledged,limit:valid?creditLimitForPledge(pledged):0,count:funds.filter(f=>f.pledged>0).length}}
function validOnboardingDetails(phone,pan,consent){return /^[6-9]\d{9}$/.test(phone)&&/^[A-Z]{5}\d{4}[A-Z]$/.test(pan)&&consent===true}
function verifyOnboardingOtp(kind,code){if(code!=='123456')return false;if(kind==='phone'&&onboarding.step===2&&validOnboardingDetails(onboarding.phone,onboarding.pan,onboarding.lookupConsent)){onboarding.phoneVerified=true;return true}if(kind==='lien'&&onboarding.step===8&&onboarding.limitReviewed&&onboarding.ckycVerified&&onboardingSelection().valid){onboarding.lienOtpVerified=true;return true}return false}
function invalidateOnboardingPledge(){onboarding.limitSeen=false;onboarding.limitReviewed=false;onboarding.lienOtpVerified=false;onboarding.lienMarked=false;onboarding.esignConsent=false}
function canEnterOnboardingStep(step){const o=onboarding,s=onboardingSelection();if(step===1)return true;if(!validOnboardingDetails(o.phone,o.pan,o.lookupConsent))return false;if(step===2)return true;if(!o.phoneVerified)return false;if(step===3)return true;if(!o.portfolioFetched)return false;if(step===4)return true;if(!s.valid)return false;if(step===5)return true;if(!o.limitSeen)return false;if(step===6)return true;if(!o.limitReviewed)return false;if(step===7)return true;if(!o.ckycVerified)return false;if(step===8)return true;if(!o.lienOtpVerified)return false;if(step===9)return true;return step===10&&o.lienMarked}
function cancelOnboardingTimers(){onboardingProgressToken++;onboardingTimers.forEach(clearTimeout);onboardingTimers=[];onboarding.busy=false}
function paintOnboarding(focus=true){render();if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})}}
function goOnboardingStep(step){if(!canEnterOnboardingStep(step))return false;cancelOnboardingTimers();onboarding.step=step;onboarding.error='';paintOnboarding();if(step===3&&!onboarding.portfolioFetched)startOnboardingProgress('portfolio');if(step===9&&!onboarding.lienMarked)startOnboardingProgress('lien');return true}
function startOnboarding(){closeDialog();cancelOnboardingTimers();onboarding=newOnboarding();if(route==='onboarding')paintOnboarding();else navTo('onboarding')}
function startOnboardingProgress(kind){if(onboarding.busy)return;const expected={portfolio:3,ckyc:7,lien:9,esign:10}[kind];if(onboarding.step!==expected||!canEnterOnboardingStep(expected))return;if(kind==='ckyc'&&!onboarding.kycConsent)return;if(kind==='esign'&&(!onboarding.esignConsent||onboarding.signature.trim().toUpperCase()!=='RAHUL SINGH'))return;onboarding.busy=true;onboarding.progress=0;onboarding.error='';const token=++onboardingProgressToken;paintOnboarding(false);[1,2,3].forEach((phase,index)=>{onboardingTimers.push(setTimeout(()=>{if(token!==onboardingProgressToken||route!=='onboarding'||onboarding.step!==expected)return;onboarding.progress=phase;if(phase===3){onboarding.busy=false;if(kind==='portfolio')onboarding.portfolioFetched=true;if(kind==='ckyc')onboarding.ckycVerified=true;if(kind==='lien')onboarding.lienMarked=true;if(kind==='esign'){finishOnboarding();return}}paintOnboarding(phase===3)},(index+1)*650))})}
function resumeOnboardingProgress(){if(onboarding.step===3&&!onboarding.portfolioFetched)startOnboardingProgress('portfolio');if(onboarding.step===9&&!onboarding.lienMarked)startOnboardingProgress('lien')}
function newOnboardedMember(){if(!canEnterOnboardingStep(10)||!onboarding.esignConsent||onboarding.signature.trim().toUpperCase()!=='RAHUL SINGH')return null;const s=onboardingSelection(),member=initial();member.funds=s.funds.map(({id,name,type,value,pledged})=>({id,name,type,value,pledged}));member.memberStatus='active';member.freshAccount=true;member.onboardingCompleted=true;member.welcomeVisible=true;member.outstanding=0;member.bill=0;member.payments=[];member.frozen=false;member.spendCap=Math.min(100000,s.limit);member.rewards={...initialRewards(),availablePoints:0,pendingPoints:0,orders:[],redemptions:[]};member.onboardingReceipt={pledged:s.pledged,limit:s.limit,advancePercent:55,ckyc:'verified',lien:'marked',agreement:'demo-signed'};return member}
function finishOnboarding(){if(onboarding.step!==10||onboarding.progress!==3)return false;const member=newOnboardedMember();if(!member)return false;state=member;memberAccess=true;save();cancelOnboardingTimers();onboarding=newOnboarding();rewardChartRange='6M';rewardChartMonth=null;rewardFilter='All';hubAllocation='100';hubHistoryFilter='All';navTo('home');toast('Your Eleva card is unlocked. Welcome in.');return true}
function onboardingWelcome(){return state.welcomeVisible?`<section class="onboard-welcome" aria-label="Card unlocked"><div class="onboard-welcome-icon">${icon('check',22)}</div><div><strong>You’re in. Your Eleva card is unlocked.</strong><p>${money(totals().pledged)} pledged · ${money(totals().limit)} ready to spend · ₹0 outstanding</p></div><button class="icon-button" data-action="onboard-dismiss-welcome" aria-label="Dismiss welcome">${icon('close',17)}</button></section>`:''}
function maskedOnboardingPhone(){return '+91 ••••••'+esc(onboarding.phone.slice(-4))}
function maskedOnboardingPan(){return '••••••'+esc(onboarding.pan.slice(-4))}
function onboardingButton(label,action='onboard-next',disabled=false){return `<button class="primary-button full" type="button" data-action="${action}" ${disabled?'disabled':''}>${label} ${icon('arrow',17)}</button>`}
function onboardingError(){return `<p class="onboard-error" id="onboarding-error" role="alert">${esc(onboarding.error)}</p>`}
function onboardingOtp(kind){const isLien=kind==='lien';return `<div class="onboard-round-icon">${icon(isLien?'shield':'mail',25)}</div><h1>${isLien?'Your pledge. Your permission.':'A quick hello to your phone.'}</h1><p class="onboard-lead">${isLien?'Authorise a lien on only the funds and amounts you selected.':'Verify your mobile number to continue.'} A demo code is ready for ${maskedOnboardingPhone()}.</p>${isLien?`<div class="onboard-mini-summary"><span>Authorising ${money(onboardingSelection().pledged)}</span><strong>${onboardingSelection().count} selected ${onboardingSelection().count===1?'fund':'funds'}</strong></div>`:''}<form id="onboarding-form" novalidate><label for="onboard-otp">${isLien?'Lien authorisation OTP':'Mobile verification OTP'}</label><input class="onboard-otp" id="onboard-otp" name="otp" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="••••••" aria-describedby="otp-hint onboarding-error"><div class="onboard-otp-helper" id="otp-hint"><span>Demo OTP <strong>123456</strong></span><button type="button" data-action="onboard-use-otp">Use demo OTP</button></div>${onboardingError()}<button class="primary-button full" type="submit">${isLien?'Authorise demo lien':'Verify & find my portfolio'} ${icon('arrow',17)}</button></form><button class="onboard-resend" data-action="onboard-resend">Resend demo OTP</button><p class="onboard-note" id="otp-resend-status" role="status">No SMS is sent. This code works only in the prototype.</p>`}
function onboardingProgressMarkup(kind){const lines={portfolio:['Matching your PAN','Finding linked mutual fund folios','Checking eligible portfolio value'],ckyc:['Looking up a sample CKYC record','Matching demo identity details','Completing the identity check'],lien:['Sending your demo authorisation','Marking selected fund amounts','Confirming your card backing'],esign:['Preparing the demo agreement','Applying your simulated signature','Unlocking your Eleva card']}[kind];return `<div class="onboard-progress-list" aria-live="polite">${lines.map((line,i)=>`<div class="${onboarding.progress>i?'complete':onboarding.progress===i?'current':''}"><span>${onboarding.progress>i?icon('check',16):String(i+1).padStart(2,'0')}</span><p>${line}</p>${onboarding.progress===i&&onboarding.busy?'<i class="onboard-spinner"></i>':''}</div>`).join('')}</div>`}
function onboardingFundPercentage(id){const fund=onboardingFunds.find(f=>f.id===id);if(!fund)return null;const amount=onboarding.amounts[id];if(amount===undefined||amount==='')return onboarding.selected[id]?null:100;return [25,50,100].find(percent=>Math.floor(fund.value*percent/100)===Number(amount))||null}
function setOnboardingFundPercentage(id,percent){const fund=onboardingFunds.find(f=>f.id===id);if(!fund||![25,50,100].includes(percent)||!onboarding.selected[id])return false;onboarding.amounts[id]=Math.floor(fund.value*percent/100);invalidateOnboardingPledge();return true}
function updateOnboardingPercentControls(id){const percent=onboardingFundPercentage(id);$$(`[data-action="onboard-fund-percent"][data-id="${id}"]`).forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.percent)===percent)))}
function onboardingFundRows(){return onboardingFunds.map(f=>{const selected=!!onboarding.selected[f.id],amount=onboarding.amounts[f.id]||'';return `<article class="onboard-fund ${selected?'selected':''}" data-onboard-fund="${f.id}"><label class="onboard-fund-select"><input type="checkbox" data-onboard-select="${f.id}" ${selected?'checked':''} aria-label="Select ${f.name}"><span class="onboard-fund-logo ${f.color}">${f.name[0]}</span><span><strong>${f.name}</strong><small>${f.type} · Folio ${f.folio}</small></span></label><div class="onboard-fund-value"><span>Portfolio value</span><strong>${money(f.value)}</strong><small>Eligible to pledge</small></div><div class="onboard-fund-amount"><label for="pledge-${f.id}">Amount to pledge</label><div><span aria-hidden="true">₹</span><input id="pledge-${f.id}" data-onboard-amount="${f.id}" type="number" min="1" max="${f.value}" step="1" inputmode="numeric" value="${selected?esc(amount):''}" placeholder="0" ${selected?'':'disabled'} aria-label="Pledge amount for ${f.name}" aria-describedby="selection-error"></div><div class="onboard-fund-percent" role="group" aria-label="Pledge percentage for ${f.name}">${[25,50,100].map(percent=>`<button type="button" data-action="onboard-fund-percent" data-id="${f.id}" data-percent="${percent}" aria-pressed="${onboardingFundPercentage(f.id)===percent}" ${selected?'':'disabled'}>${percent}%</button>`).join('')}</div></div></article>`}).join('')}
function onboardingReviewRows(){return onboardingSelection().funds.filter(f=>f.pledged>0).map(f=>`<div class="onboard-review-fund"><span>${f.name}<small>${f.type}</small></span><strong>${money(f.pledged)}</strong></div>`).join('')}
function onboardingStepContent(){const o=onboarding,s=onboardingSelection();switch(o.step){
case 1:return `<div class="onboard-eyebrow">YOUR WEALTH SHOULD COUNT</div><h1>Let’s make<br>room for you.</h1><p class="onboard-lead">A card backed by what you’ve built. Start with your mobile number and PAN.</p><form id="onboarding-form" novalidate><label for="onboard-phone">Mobile number</label><div class="onboard-phone"><span>+91</span><input id="onboard-phone" type="tel" inputmode="numeric" autocomplete="off" maxlength="10" value="${esc(o.phone)}" placeholder="10-digit mobile number" aria-describedby="onboarding-error"></div><label for="onboard-pan">PAN</label><input id="onboard-pan" class="onboard-pan" type="text" autocomplete="off" maxlength="10" value="${esc(o.pan)}" placeholder="ABCDE1234F" aria-describedby="pan-help onboarding-error"><p id="pan-help" class="onboard-field-help">We’ll simulate finding the mutual funds linked to your PAN.</p><label class="onboard-consent"><input id="onboard-lookup-consent" type="checkbox" ${o.lookupConsent?'checked':''}><span>I agree to the simulated portfolio lookup using these details.</span></label>${onboardingError()}<button class="primary-button full" type="submit">Get started ${icon('arrow',17)}</button></form><button class="onboard-sample" data-action="onboard-sample">Use sample details ${icon('arrowUp',13)}</button><p class="onboard-note">Private demo. Use made-up details. No SMS, PAN lookup or financial instruction is sent. Your inputs are discarded when you finish or leave setup.</p>`;
case 2:return onboardingOtp('phone');
case 3:return `<div class="onboard-round-icon">${icon(o.portfolioFetched?'check':'search',25)}</div><h1>${o.portfolioFetched?'Your wealth,<br>found.':'Finding what<br>you’ve built.'}</h1><p class="onboard-lead">${o.portfolioFetched?'Three mutual funds. One portfolio ready to open up new possibilities.':'Simulating a portfolio lookup for PAN '+maskedOnboardingPan()+'.'}</p>${onboardingProgressMarkup('portfolio')}${o.portfolioFetched?`<div class="onboard-found"><span>Linked portfolio · 3 funds</span><strong>₹12,00,000</strong><small>Sample values · no real folios accessed</small></div>${onboardingButton('Choose funds to pledge')}`:'<p class="onboard-note">Matching a fictional portfolio. This takes a moment.</p>'}`;
case 4:return `<div class="onboard-eyebrow">YOUR PORTFOLIO. YOUR CHOICE.</div><h1>Choose what<br>backs your card.</h1><p class="onboard-lead">Select a fund, then choose 25%, 50% or 100% to pledge. Each fund starts at 100%; your investments stay invested.</p><div class="onboard-portfolio-meta"><span>Linked portfolio <strong>₹12,00,000</strong></span><button data-action="onboard-select-all">Select all funds</button><button data-action="onboard-clear">Clear</button></div><div class="onboard-funds">${onboardingFundRows()}</div><p id="selection-error" class="onboard-error" role="status"></p><div class="onboard-live-limit" aria-live="polite"><div><span>Selected pledge</span><strong id="onboard-pledge-total">${money(s.pledged||0)}</strong></div><div><span>Your credit limit</span><strong id="onboard-live-credit">${money(s.limit)}</strong></div></div><p class="onboard-field-help">55% of your total pledge, rounded up to the nearest ₹1,000.</p>${onboardingButton('See my limit','onboard-next',!s.valid)}<p class="onboard-note">These are sample fund holdings, not an investment recommendation.</p>`;
case 5:return `<div class="onboard-eyebrow">BACKED BY YOUR AMBITION</div><h1>A little more<br>room to move.</h1><p class="onboard-lead">Here’s the spending power your selected investments unlock.</p><div class="onboard-limit-reveal"><span>Your Eleva credit limit</span><strong>${money(s.limit)}</strong><small>Against ${money(s.pledged)} pledged investments</small><div><span>55% advance rate</span><span>Rounded up to ₹1,000</span></div></div><div class="onboard-keep-invested">${icon('leaf',22)}<p>Your units stay invested. Only the amount you chose will be marked as security for your card.</p></div>${onboardingButton('Review my limit')}<button class="onboard-sample" data-action="onboard-edit-funds">Change my pledge</button>`;
case 6:return `<div class="onboard-eyebrow">A CLEAR PICTURE</div><h1>Your backing.<br>Your limit.</h1><p class="onboard-lead">Review your pledge before we verify your identity.</p><div class="onboard-review-box"><div class="spread"><h2>Selected funds</h2><button data-action="onboard-edit-funds">Edit</button></div>${onboardingReviewRows()}<div class="onboard-review-total"><span>Total pledge</span><strong>${money(s.pledged)}</strong></div></div><div class="onboard-review-limit"><span>Approved demo limit</span><strong>${money(s.limit)}</strong><small>55% of pledge · rounded up to ₹1,000</small></div><p class="onboard-note">Pledged funds cannot be redeemed while under lien. Portfolio values can change, which may affect your limit. This prototype creates no real lien or credit facility.</p>${onboardingButton('Confirm limit & continue')}`;
case 7:return `<div class="onboard-round-icon">${icon(o.ckycVerified?'check':'shield',25)}</div><h1>${o.ckycVerified?'Identity verified.<br>One step closer.':'A familiar identity.<br>A fresh beginning.'}</h1><p class="onboard-lead">${o.ckycVerified?'Your simulated CKYC check is complete. You can now authorise your selected pledge.':'We’ll simulate checking your identity against a CKYC record.'}</p><div class="onboard-identity"><span class="onboard-avatar">RS</span><div><strong>Rahul Singh</strong><span>Sample CKYC profile</span></div><span class="onboard-status ${o.ckycVerified?'verified':''}">${o.ckycVerified?'Verified':'Ready to check'}</span></div><div class="onboard-identity-details"><div><span>PAN</span><strong>${maskedOnboardingPan()}</strong></div><div><span>CKYC record</span><strong>•••• •••• •• 4201</strong></div><div><span>Address</span><strong>Gurugram, Haryana · sample</strong></div></div>${o.busy?onboardingProgressMarkup('ckyc'):o.ckycVerified?onboardingButton('Continue to lien authorisation'):`<label class="onboard-consent"><input id="onboard-kyc-consent" type="checkbox" ${o.kycConsent?'checked':''}><span>I agree to the simulated CKYC check using a fictional identity record.</span></label>${onboardingButton('Simulate CKYC check','onboard-ckyc',!o.kycConsent)}`}<p class="onboard-note">No government record is accessed. No documents or real KYC information are collected.</p>`;
case 8:return onboardingOtp('lien');
case 9:return `<div class="onboard-round-icon">${icon(o.lienMarked?'check':'lock',25)}</div><h1>${o.lienMarked?'Backed. Ready<br>for what’s next.':'Putting your<br>backing in place.'}</h1><p class="onboard-lead">${o.lienMarked?'Your selected fund amounts are now marked as pledged in this demo.':'Simulating lien marking for only the investments you authorised.'}</p><div class="onboard-mini-summary"><span>${money(s.pledged)} across ${s.count} ${s.count===1?'fund':'funds'}</span><strong>${money(s.limit)} credit limit</strong></div>${onboardingProgressMarkup('lien')}${o.lienMarked?onboardingButton('Review & e-sign'):'<p class="onboard-note">Please keep this page open while the demo completes.</p>'}<p class="onboard-note">No instruction is sent to an AMC, registrar or lender.</p>`;
case 10:return `<div class="onboard-eyebrow">THE LAST LITTLE STEP</div><h1>Make it yours.</h1><p class="onboard-lead">Review your demo card agreement and add your simulated e-signature.</p><div class="onboard-agreement-summary"><span>ELEVA SIGNATURE</span><strong>${money(s.limit)} credit limit</strong><small>${money(s.pledged)} pledged · ${s.count} ${s.count===1?'fund':'funds'}</small><div><span>${icon('check',13)} CKYC verified</span><span>${icon('check',13)} Lien marked</span></div></div><details class="onboard-agreement" open><summary>Review demo agreement</summary><div><p><strong>1. Your card backing.</strong> The selected fund amounts (${money(s.pledged)}) secure a demo limit of ${money(s.limit)}. The 55% advance is rounded up to the nearest ₹1,000.</p><p><strong>2. Your investments.</strong> Units remain invested. Pledged amounts stay under lien until released. Changes in fund value may reduce available credit or require more backing or repayment.</p><p><strong>3. Your responsibility.</strong> Card spends would create dues payable by the statement due date. This new demo card starts with ₹0 dues.</p><p><strong>4. Prototype only.</strong> This is a simulated agreement. It has no legal effect, creates no real card or lien, and submits no signature to a third party. Live pricing and lender terms are outside this prototype.</p></div></details>${o.busy?onboardingProgressMarkup('esign'):`<form id="onboarding-form" novalidate><label for="onboard-signature">Type the sample cardholder name</label><input id="onboard-signature" autocomplete="off" value="${esc(o.signature)}" placeholder="Rahul Singh" aria-describedby="onboarding-error"><label class="onboard-consent"><input id="onboard-esign-consent" type="checkbox" ${o.esignConsent?'checked':''}><span>I have reviewed the demo agreement and agree to apply a simulated e-signature.</span></label>${onboardingError()}<button type="submit" class="primary-button full">Simulate e-sign & unlock card ${icon('arrow',17)}</button></form>`}<p class="onboard-note">A simulation only. No real signature or credit agreement is created.</p>`;
default:return ''}}
function onboardingPage(){const o=onboarding,group=o.step<=2?0:o.step<=4?1:o.step<=6?2:o.step<=9?3:4;return `<div class="onboarding-shell"><aside class="onboarding-brand-panel"><a class="brand" ${memberAccess?'href="#home"':'href="#onboarding"'} aria-label="Eleva">${mark()}eleva</a><div class="onboarding-brand-copy"><span>INDEPENDENT BY CHOICE.</span><h2>Your wealth.<br>Your <em>next move.</em></h2><p>Built around what you’ve created.<br>Ready for where you’re going.</p></div><div class="onboarding-card"><img src="./assets/eleva-card-signature.png" width="870" height="550" alt="The real Eleva Signature card, brushed black with silver artwork"><span>${icon('lock',12)} Unlock your Eleva Signature</span></div><ol class="onboarding-milestones" aria-label="Onboarding stages">${['Your details','Your portfolio','Your limit','Verification','Your card'].map((title,i)=>`<li class="${i<group?'done':i===group?'active':''}" ${i===group?'aria-current="step"':''}><span>${i<group?icon('check',12):i+1}</span>${title}</li>`).join('')}</ol><p class="onboarding-brand-footnote">YOUR WEALTH. YOUR CREDIT.</p></aside><div class="onboarding-main-wrap"><header class="onboarding-header"><a class="brand" href="#onboarding" aria-label="Eleva">${mark()}eleva</a><span class="onboarding-demo-badge">PRIVATE DEMO</span>${memberAccess?'<button data-action="onboard-exit">Back to app '+icon('close',14)+'</button>':''}</header><main id="main" class="onboarding-main" tabindex="-1"><div class="onboarding-step-meta"><span>STEP ${String(o.step).padStart(2,'0')} / 10</span><span>${onboardingStepTitles[o.step-1]}</span></div><div class="onboarding-step-track"><span style="width:${o.step*10}%"></span></div>${o.step>1&&!o.busy?'<button class="onboarding-back" data-action="onboard-back">'+icon('arrow',14)+' Back</button>':''}<div class="onboarding-content">${onboardingStepContent()}</div><footer class="onboarding-footer">${icon('shield',13)} Private prototype · all verification and financial steps are simulated</footer></main></div></div>`}
function onboardingSetError(message){onboarding.error=message;const error=$('#onboarding-error');if(error){error.textContent=message;error.focus?.()}return false}
function onboardingSubmit(){const o=onboarding;if(o.busy)return;switch(o.step){case 1:{o.phone=$('#onboard-phone').value.trim();o.pan=$('#onboard-pan').value.trim().toUpperCase();o.lookupConsent=$('#onboard-lookup-consent').checked;if(!/^[6-9]\d{9}$/.test(o.phone))return onboardingSetError('Enter a 10-digit Indian mobile number starting with 6, 7, 8 or 9.');if(!/^[A-Z]{5}\d{4}[A-Z]$/.test(o.pan))return onboardingSetError('Use PAN format ABCDE1234F: five letters, four digits and one letter.');if(!o.lookupConsent)return onboardingSetError('Agree to the simulated portfolio lookup to continue.');goOnboardingStep(2);break}case 2:case 8:{if(!verifyOnboardingOtp(o.step===2?'phone':'lien',$('#onboard-otp').value.trim()))return onboardingSetError('That code does not match. Use demo OTP 123456.');goOnboardingStep(o.step===2?3:9);break}case 10:{o.signature=$('#onboard-signature').value.trim();o.esignConsent=$('#onboard-esign-consent').checked;if(o.signature.toUpperCase()!=='RAHUL SINGH')return onboardingSetError('Type Rahul Singh to match the sample cardholder.');if(!o.esignConsent)return onboardingSetError('Review and agree to the demo agreement before e-signing.');startOnboardingProgress('esign');break}}}
function onboardingNext(){if(onboarding.busy)return;switch(onboarding.step){case 3:if(onboarding.portfolioFetched)goOnboardingStep(4);break;case 4:if(onboardingSelection().valid)goOnboardingStep(5);break;case 5:onboarding.limitSeen=true;goOnboardingStep(6);break;case 6:onboarding.limitReviewed=true;goOnboardingStep(7);break;case 7:if(onboarding.ckycVerified)goOnboardingStep(8);break;case 9:if(onboarding.lienMarked)goOnboardingStep(10);break}}
function updateOnboardingSelection(){const s=onboardingSelection();$('#onboard-pledge-total').textContent=Number.isFinite(s.pledged)?money(s.pledged):'—';$('#onboard-live-credit').textContent=s.valid?money(s.limit):'₹0';const button=$('[data-action="onboard-next"]');if(button)button.disabled=!s.valid;$('#selection-error').textContent=Object.values(onboarding.selected).some(Boolean)&&!s.valid?'Enter whole rupees above ₹0 and within each selected fund’s value.':''}
function onboardingInput(el){if(onboarding.error){onboarding.error='';const error=$('#onboarding-error');if(error)error.textContent=''}if(el.id==='onboard-phone'||el.id==='onboard-pan'){const key=el.id==='onboard-phone'?'phone':'pan';let value=el.value;if(key==='pan'){value=value.toUpperCase();el.value=value}if(onboarding[key]!==value){onboarding[key]=value;onboarding.phoneVerified=false;onboarding.portfolioFetched=false;onboarding.ckycVerified=false;invalidateOnboardingPledge()}}if(el.dataset.onboardAmount){onboarding.amounts[el.dataset.onboardAmount]=el.value;invalidateOnboardingPledge();updateOnboardingPercentControls(el.dataset.onboardAmount);updateOnboardingSelection()}if(el.id==='onboard-signature')onboarding.signature=el.value}
function onboardingChange(el){if(el.id==='onboard-lookup-consent'){onboarding.lookupConsent=el.checked;if(!el.checked){onboarding.phoneVerified=false;onboarding.portfolioFetched=false;onboarding.ckycVerified=false;invalidateOnboardingPledge()}}if(el.dataset.onboardSelect){const id=el.dataset.onboardSelect;onboarding.selected[id]=el.checked;if(el.checked&&!Number(onboarding.amounts[id]))onboarding.amounts[id]=onboardingFunds.find(f=>f.id===id).value;invalidateOnboardingPledge();paintOnboarding(false);$(`[data-onboard-select="${id}"]`).focus();updateOnboardingSelection()}if(el.id==='onboard-kyc-consent'){onboarding.kycConsent=el.checked;$('[data-action="onboard-ckyc"]').disabled=!el.checked}if(el.id==='onboard-esign-consent')onboarding.esignConsent=el.checked}
const onboardingActions={
'onboard-start':startOnboarding,
'onboard-exit':()=>{if(!memberAccess)return;cancelOnboardingTimers();onboarding=newOnboarding();navTo('home')},
'onboard-sample':()=>{onboarding.error='';onboarding.phone='9876543210';onboarding.pan='ABCDE1234F';onboarding.phoneVerified=false;onboarding.portfolioFetched=false;onboarding.ckycVerified=false;invalidateOnboardingPledge();paintOnboarding(false);$('#onboard-lookup-consent').focus()},
'onboard-next':onboardingNext,
'onboard-back':()=>{const step=onboarding.step;if(step===10){invalidateOnboardingPledge();goOnboardingStep(4);return}goOnboardingStep(({2:1,3:1,4:1,5:4,6:4,7:6,8:7,9:8})[step]||1)},
'onboard-edit-funds':()=>{invalidateOnboardingPledge();goOnboardingStep(4)},
'onboard-use-otp':()=>{$('#onboard-otp').value='123456';$('#onboard-otp').focus()},
'onboard-resend':()=>{$('#otp-resend-status').textContent='Demo code refreshed: 123456. No SMS was sent.'},
'onboard-ckyc':()=>startOnboardingProgress('ckyc'),
'onboard-select-all':()=>{onboardingFunds.forEach(f=>{onboarding.selected[f.id]=true;onboarding.amounts[f.id]=f.value});invalidateOnboardingPledge();paintOnboarding(false)},
'onboard-clear':()=>{onboarding.selected={};onboarding.amounts={};invalidateOnboardingPledge();paintOnboarding(false)},
'onboard-fund-percent':el=>{const id=el.dataset.id;if(!setOnboardingFundPercentage(id,Number(el.dataset.percent)))return;$(`#pledge-${id}`).value=onboarding.amounts[id];updateOnboardingPercentControls(id);updateOnboardingSelection()},
'onboard-dismiss-welcome':()=>{state.welcomeVisible=false;save();render()}
};
